import React, { useEffect, useState } from 'react'
import PACK_OF_CARDS from '../utils/packOfCards'
import shuffleArray from '../utils/shuffleArray'
import io from 'socket.io-client'
import queryString from 'query-string'
import Spinner from './Spinner'
import useSound from 'use-sound'

import bgMusic from '../assets/sounds/game-bg-music.mp3'
import unoSound from '../assets/sounds/uno-sound.mp3'
import shufflingSound from '../assets/sounds/shuffling-cards-1.mp3'
import skipCardSound from '../assets/sounds/skip-sound.mp3'
import draw2CardSound from '../assets/sounds/draw2-sound.mp3'
import wildCardSound from '../assets/sounds/wild-sound.mp3'
import draw4CardSound from '../assets/sounds/draw4-sound.mp3'
import gameOverSound from '../assets/sounds/game-over-sound.mp3'

//NUMBER CODES FOR ACTION CARDS
//SKIP - 404
//DRAW 2 - 252
//WILD - 300
//DRAW 4 WILD - 600

let socket
// Auto-detect server endpoint based on current host
const isProd = (window.location.hostname === 'pichain.net' || window.location.hostname === 'www.pichain.net')
const ENDPOINT = isProd
    ? window.location.protocol + '//' + window.location.hostname
    : 'http://localhost:8418'

const Game = (props) => {
    const data = queryString.parse(props.location.search)

    //initialize socket state
    const [room, setRoom] = useState(data.roomCode)
    const [roomFull, setRoomFull] = useState(false)
    const [users, setUsers] = useState([])
    const [currentUser, setCurrentUser] = useState('')
    const currentUserRef = React.useRef('')
    const [message, setMessage] = useState('')
    const [messages, setMessages] = useState([])

    useEffect(() => {
        const connectionOptions =  {
            "forceNew" : true,
            "reconnectionAttempts": "Infinity",
            "timeout" : 10000,
            "transports" : ["websocket"],
            ...(isProd ? { "path": "/ws/uno/socket.io/" } : {})
        }
        socket = io.connect(ENDPOINT, connectionOptions)

        socket.emit('join', {room: room}, (error) => {
            if(error)
                setRoomFull(true)
        })

        //cleanup on component unmount
        return function cleanup() {
            socket.emit('disconnect')
            //shut down connnection instance
            socket.off()
        }
    }, [])

    //initialize game state
    const [gameOver, setGameOver] = useState(true)
    const [winner, setWinner] = useState('')
    const [turn, setTurn] = useState('')
    const [playerDecks, setPlayerDecks] = useState({})
    const [playerOrder, setPlayerOrder] = useState([])
    const [direction, setDirection] = useState(1) // 1=clockwise, -1=counter
    const [currentColor, setCurrentColor] = useState('')
    const [currentNumber, setCurrentNumber] = useState('')
    const [playedCardsPile, setPlayedCardsPile] = useState([])
    const [drawCardPile, setDrawCardPile] = useState([])
    const [gameStarted, setGameStarted] = useState(false)

    const [isChatBoxHidden, setChatBoxHidden] = useState(true)
    const [isUnoButtonPressed, setUnoButtonPressed] = useState(false)
    const [isSoundMuted, setSoundMuted] = useState(false)
    const [isMusicMuted, setMusicMuted] = useState(true)

    const [playBBgMusic, { pause }] = useSound(bgMusic, { loop: true })
    const [playUnoSound] = useSound(unoSound)
    const [playShufflingSound] = useSound(shufflingSound)
    const [playSkipCardSound] = useSound(skipCardSound)
    const [playDraw2CardSound] = useSound(draw2CardSound)
    const [playWildCardSound] = useSound(wildCardSound)
    const [playDraw4CardSound] = useSound(draw4CardSound)
    const [playGameOverSound] = useSound(gameOverSound)

    // Helper: get next player in turn order
    const getNextPlayer = (current, order, dir, skip = 0) => {
        const idx = order.indexOf(current)
        const steps = 1 + skip
        const next = ((idx + dir * steps) % order.length + order.length) % order.length
        return order[next]
    }

    //runs once on component mount
    useEffect(() => {
        // Game initialization is deferred until enough players join
    }, [])

    // Start game when we have 2+ players and current user is Player 1
    const startGame = () => {
        if(gameStarted) return
        const numPlayers = users.length
        if(numPlayers < 2) return

        const shuffledCards = shuffleArray(PACK_OF_CARDS)
        const order = users.map(u => u.name)
        const decks = {}

        // Deal 7 cards to each player
        for(const name of order) {
            decks[name] = shuffledCards.splice(0, 7)
        }

        // Find a non-action starting card
        let startingCardIndex
        while(true) {
            startingCardIndex = Math.floor(Math.random() * shuffledCards.length)
            const c = shuffledCards[startingCardIndex]
            if(c === 'W' || c === 'D4W' || c.startsWith('skip') || c.startsWith('_') || c.startsWith('D2')) {
                continue
            }
            break
        }

        const pile = shuffledCards.splice(startingCardIndex, 1)
        const drawPile = shuffledCards

        socket.emit('initGameState', {
            gameOver: false,
            turn: order[0],
            playerDecks: decks,
            playerOrder: order,
            direction: 1,
            currentColor: pile[0].charAt(1),
            currentNumber: pile[0].charAt(0),
            playedCardsPile: [...pile],
            drawCardPile: [...drawPile]
        })
        setGameStarted(true)
    }

    useEffect(() => {
        socket.on('initGameState', (state) => {
            setGameOver(state.gameOver)
            setTurn(state.turn)
            setPlayerDecks(state.playerDecks)
            setPlayerOrder(state.playerOrder)
            setDirection(state.direction || 1)
            setCurrentColor(state.currentColor)
            setCurrentNumber(state.currentNumber)
            setPlayedCardsPile(state.playedCardsPile)
            setDrawCardPile(state.drawCardPile)
            setGameStarted(true)
        })

        socket.on('updateGameState', (state) => {
            if(state.gameOver !== undefined) setGameOver(state.gameOver)
            if(state.gameOver === true) playGameOverSound()
            if(state.winner) {
                setWinner(state.winner)
                // Report winner to parent frame for PVP integration
                if(state.gameOver === true && window.parent !== window) {
                    try {
                        window.parent.postMessage({
                            type: 'uno_game_over',
                            winner: state.winner,
                            isLocalWinner: state.winner === currentUserRef.current
                        }, '*')
                    } catch(_e){}
                }
            }
            if(state.turn) setTurn(state.turn)
            if(state.playerDecks) setPlayerDecks(state.playerDecks)
            if(state.playerOrder) setPlayerOrder(state.playerOrder)
            if(state.direction !== undefined) setDirection(state.direction)
            if(state.currentColor) setCurrentColor(state.currentColor)
            if(state.currentNumber !== undefined) setCurrentNumber(state.currentNumber)
            if(state.playedCardsPile) setPlayedCardsPile(state.playedCardsPile)
            if(state.drawCardPile) setDrawCardPile(state.drawCardPile)
            setUnoButtonPressed(false)
        })

        socket.on("roomData", ({ users }) => {
            setUsers(users)
        })

        socket.on('currentUserData', ({ name }) => {
            setCurrentUser(name)
            currentUserRef.current = name
        })

        socket.on('message', message => {
            setMessages(messages => [ ...messages, message ])
            const chatBody = document.querySelector('.chat-body')
            if(chatBody) chatBody.scrollTop = chatBody.scrollHeight
        })
    }, [])

    //some util functions
    const checkGameOver = (deck) => {
        return deck.length === 1
    }

    const checkWinner = (deck, player) => {
        return deck.length === 1 ? player : ''
    }

    const toggleChatBox = () => {
        const chatBody = document.querySelector('.chat-body')
        if(isChatBoxHidden) {
            chatBody.style.display = 'block'
            setChatBoxHidden(false)
        }
        else {
            chatBody.style.display = 'none'
            setChatBoxHidden(true)
        }
    }

    const sendMessage = (event) => {
        event.preventDefault()
        if(message) {
            socket.emit('sendMessage', { message: message }, () => {
                setMessage('')
            })
        }
    }

    // Core helper: play a card from current player's deck
    const playCard = (played_card, currentPlayerName, myDeck, newColor, soundFn) => {
        const removeIndex = myDeck.indexOf(played_card)
        const copiedDraw = [...drawCardPile]
        const updatedDecks = { ...playerDecks }
        let updatedDeck = [...myDeck.slice(0, removeIndex), ...myDeck.slice(removeIndex + 1)]
        let newDirection = direction
        let nextPlayer

        // UNO penalty check
        if(updatedDeck.length === 1 && myDeck.length === 2 && !isUnoButtonPressed) {
            alert('Oops! You forgot to press UNO. You drew 2 cards as penalty.')
            const pen1 = copiedDraw.pop()
            const pen2 = copiedDraw.pop()
            if(pen1) updatedDeck.push(pen1)
            if(pen2) updatedDeck.push(pen2)
        }

        updatedDecks[currentPlayerName] = updatedDeck

        // Determine card type and effects
        const isSkip = played_card.startsWith('skip')
        const isReverse = played_card.startsWith('_') && played_card.length === 2
        const isDraw2 = played_card.startsWith('D2')
        const isWild = played_card === 'W'
        const isDraw4 = played_card === 'D4W'

        // Compute color/number
        let cardColor, cardNumber
        if(isWild || isDraw4) {
            cardColor = newColor
            cardNumber = isDraw4 ? 600 : 300
        } else if(isSkip) {
            cardColor = played_card.charAt(4)
            cardNumber = 404
        } else if(isReverse) {
            cardColor = played_card.charAt(1)
            cardNumber = '_'
        } else if(isDraw2) {
            cardColor = played_card.charAt(2)
            cardNumber = 252
        } else {
            cardColor = played_card.charAt(1)
            cardNumber = played_card.charAt(0)
        }

        // Reverse direction
        if(isReverse) {
            newDirection = -direction
            // In 2-player game, reverse acts like skip (turn stays with current player)
            if(playerOrder.length === 2) {
                nextPlayer = currentPlayerName
            } else {
                nextPlayer = getNextPlayer(currentPlayerName, playerOrder, newDirection)
            }
        }
        // Skip - skip next player
        else if(isSkip) {
            nextPlayer = getNextPlayer(currentPlayerName, playerOrder, direction, 1)
        }
        // Draw 2 - next player draws 2, skip their turn
        else if(isDraw2) {
            nextPlayer = getNextPlayer(currentPlayerName, playerOrder, direction)
            const d1 = copiedDraw.pop()
            const d2 = copiedDraw.pop()
            updatedDecks[nextPlayer] = [...(updatedDecks[nextPlayer] || []), ...(d1 ? [d1] : []), ...(d2 ? [d2] : [])]
            // Skip the drawing player's turn
            nextPlayer = getNextPlayer(nextPlayer, playerOrder, direction)
        }
        // Draw 4 - next player draws 4, skip their turn
        else if(isDraw4) {
            nextPlayer = getNextPlayer(currentPlayerName, playerOrder, direction)
            const cards = []
            for(let i = 0; i < 4; i++) {
                const c = copiedDraw.pop()
                if(c) cards.push(c)
            }
            updatedDecks[nextPlayer] = [...(updatedDecks[nextPlayer] || []), ...cards]
            nextPlayer = getNextPlayer(nextPlayer, playerOrder, direction)
        }
        else {
            nextPlayer = getNextPlayer(currentPlayerName, playerOrder, direction)
        }

        if(soundFn) soundFn()

        const isOver = checkGameOver(myDeck)
        socket.emit('updateGameState', {
            gameOver: isOver,
            winner: checkWinner(myDeck, currentPlayerName),
            turn: nextPlayer,
            playerDecks: updatedDecks,
            direction: newDirection,
            playedCardsPile: [...playedCardsPile, played_card],
            currentColor: cardColor,
            currentNumber: cardNumber,
            drawCardPile: [...copiedDraw]
        })
    }

    //driver functions
    const onCardPlayedHandler = (played_card) => {
        if(turn !== currentUser) return
        const myDeck = playerDecks[currentUser]
        if(!myDeck) return

        switch(played_card) {
            case '0R': case '1R': case '2R': case '3R': case '4R': case '5R': case '6R': case '7R': case '8R': case '9R':
            case '0G': case '1G': case '2G': case '3G': case '4G': case '5G': case '6G': case '7G': case '8G': case '9G':
            case '0B': case '1B': case '2B': case '3B': case '4B': case '5B': case '6B': case '7B': case '8B': case '9B':
            case '0Y': case '1Y': case '2Y': case '3Y': case '4Y': case '5Y': case '6Y': case '7Y': case '8Y': case '9Y': {
                const num = played_card.charAt(0)
                const col = played_card.charAt(1)
                if(currentColor === col || currentNumber === num) {
                    playCard(played_card, currentUser, myDeck, null, () => !isSoundMuted && playShufflingSound())
                } else {
                    alert('Invalid Move!')
                }
                break
            }
            case '_R': case '_G': case '_B': case '_Y': {
                const col = played_card.charAt(1)
                if(currentColor === col || currentNumber === '_') {
                    playCard(played_card, currentUser, myDeck, null, () => !isSoundMuted && playShufflingSound())
                } else {
                    alert('Invalid Move!')
                }
                break
            }
            case 'skipR': case 'skipG': case 'skipB': case 'skipY': {
                const col = played_card.charAt(4)
                if(currentColor === col || currentNumber === 404) {
                    playCard(played_card, currentUser, myDeck, null, () => !isSoundMuted && playSkipCardSound())
                } else {
                    alert('Invalid Move!')
                }
                break
            }
            case 'D2R': case 'D2G': case 'D2B': case 'D2Y': {
                const col = played_card.charAt(2)
                if(currentColor === col || currentNumber === 252) {
                    playCard(played_card, currentUser, myDeck, null, () => !isSoundMuted && playDraw2CardSound())
                } else {
                    alert('Invalid Move!')
                }
                break
            }
            case 'W': {
                const newColor = prompt('Enter first letter of new color (R/G/B/Y)')
                if(newColor) {
                    playCard(played_card, currentUser, myDeck, newColor.toUpperCase(), () => !isSoundMuted && playWildCardSound())
                }
                break
            }
            case 'D4W': {
                const newColor = prompt('Enter first letter of new color (R/G/B/Y)')
                if(newColor) {
                    playCard(played_card, currentUser, myDeck, newColor.toUpperCase(), () => !isSoundMuted && playDraw4CardSound())
                }
                break
            }
            default:
                break
        }
    }

    const onCardDrawnHandler = () => {
        if(turn !== currentUser) return
        const myDeck = playerDecks[currentUser]
        if(!myDeck) return

        const copiedDraw = [...drawCardPile]
        const drawCard = copiedDraw.pop()
        if(!drawCard) return

        const colorOfDrawnCard = drawCard.charAt(drawCard.length - 1)
        let numberOfDrawnCard = drawCard.charAt(0)

        // Check if drawn card can be auto-played
        const isActionCard = drawCard === 'W' || drawCard === 'D4W' || drawCard.startsWith('skip') || drawCard.startsWith('D2') || drawCard.startsWith('_')

        if(drawCard === 'W') {
            alert(`You drew ${drawCard}. It was played for you.`)
            const newColor = prompt('Enter first letter of new color (R/G/B/Y)')
            if(newColor) {
                !isSoundMuted && playWildCardSound()
                const updatedDecks = { ...playerDecks }
                const nextP = getNextPlayer(currentUser, playerOrder, direction)
                socket.emit('updateGameState', {
                    turn: nextP,
                    playedCardsPile: [...playedCardsPile, drawCard],
                    currentColor: newColor.toUpperCase(),
                    currentNumber: 300,
                    drawCardPile: [...copiedDraw]
                })
            }
        }
        else if(drawCard === 'D4W') {
            alert(`You drew ${drawCard}. It was played for you.`)
            const newColor = prompt('Enter first letter of new color (R/G/B/Y)')
            if(newColor) {
                !isSoundMuted && playDraw4CardSound()
                const updatedDecks = { ...playerDecks }
                const nextP = getNextPlayer(currentUser, playerOrder, direction)
                const cards = []
                for(let i = 0; i < 4; i++) { const c = copiedDraw.pop(); if(c) cards.push(c) }
                updatedDecks[nextP] = [...(updatedDecks[nextP] || []), ...cards]
                const skipNext = getNextPlayer(nextP, playerOrder, direction)
                socket.emit('updateGameState', {
                    turn: skipNext,
                    playerDecks: updatedDecks,
                    playedCardsPile: [...playedCardsPile, drawCard],
                    currentColor: newColor.toUpperCase(),
                    currentNumber: 600,
                    drawCardPile: [...copiedDraw]
                })
            }
        }
        else if(colorOfDrawnCard === currentColor && drawCard.startsWith('skip')) {
            alert(`You drew ${drawCard}. It was played for you.`)
            !isSoundMuted && playSkipCardSound()
            const skipNext = getNextPlayer(currentUser, playerOrder, direction, 1)
            socket.emit('updateGameState', {
                turn: skipNext,
                playedCardsPile: [...playedCardsPile, drawCard],
                currentColor: colorOfDrawnCard,
                currentNumber: 404,
                drawCardPile: [...copiedDraw]
            })
        }
        else if(colorOfDrawnCard === currentColor && drawCard.startsWith('D2')) {
            alert(`You drew ${drawCard}. It was played for you.`)
            !isSoundMuted && playDraw2CardSound()
            const updatedDecks = { ...playerDecks }
            const nextP = getNextPlayer(currentUser, playerOrder, direction)
            const d1 = copiedDraw.pop()
            const d2 = copiedDraw.pop()
            updatedDecks[nextP] = [...(updatedDecks[nextP] || []), ...(d1 ? [d1] : []), ...(d2 ? [d2] : [])]
            const skipNext = getNextPlayer(nextP, playerOrder, direction)
            socket.emit('updateGameState', {
                turn: skipNext,
                playerDecks: updatedDecks,
                playedCardsPile: [...playedCardsPile, drawCard],
                currentColor: colorOfDrawnCard,
                currentNumber: 252,
                drawCardPile: [...copiedDraw]
            })
        }
        else if(colorOfDrawnCard === currentColor && drawCard.startsWith('_')) {
            alert(`You drew ${drawCard}. It was played for you.`)
            !isSoundMuted && playShufflingSound()
            let newDir = -direction
            let nextP
            if(playerOrder.length === 2) {
                nextP = currentUser
            } else {
                nextP = getNextPlayer(currentUser, playerOrder, newDir)
            }
            socket.emit('updateGameState', {
                turn: nextP,
                direction: newDir,
                playedCardsPile: [...playedCardsPile, drawCard],
                currentColor: colorOfDrawnCard,
                currentNumber: '_',
                drawCardPile: [...copiedDraw]
            })
        }
        else if(numberOfDrawnCard === currentNumber || colorOfDrawnCard === currentColor) {
            alert(`You drew ${drawCard}. It was played for you.`)
            !isSoundMuted && playShufflingSound()
            const nextP = getNextPlayer(currentUser, playerOrder, direction)
            socket.emit('updateGameState', {
                turn: nextP,
                playedCardsPile: [...playedCardsPile, drawCard],
                currentColor: colorOfDrawnCard,
                currentNumber: numberOfDrawnCard,
                drawCardPile: [...copiedDraw]
            })
        }
        else {
            // Card not playable - add to player's deck and pass turn
            !isSoundMuted && playShufflingSound()
            const updatedDecks = { ...playerDecks }
            updatedDecks[currentUser] = [...myDeck, drawCard]
            const nextP = getNextPlayer(currentUser, playerOrder, direction)
            socket.emit('updateGameState', {
                turn: nextP,
                playerDecks: updatedDecks,
                drawCardPile: [...copiedDraw]
            })
        }
    }

    // Get my deck and other players' decks
    const myDeck = playerDecks[currentUser] || []
    const otherPlayers = playerOrder.filter(p => p !== currentUser)

    return (
        <div className={`Game backgroundColorR backgroundColor${currentColor}`}>
            {(!roomFull) ? <>

                <div className='topInfo'>
                    <img src={require('../assets/logo.png').default} />
                    <h1>Game Code: {room}</h1>
                    <span>
                        <button className='game-button green' onClick={() => setSoundMuted(!isSoundMuted)}>{isSoundMuted ? <span className="material-icons">volume_off</span> : <span className="material-icons">volume_up</span>}</button>
                        <button className='game-button green' onClick={() => {
                            if(isMusicMuted)
                                playBBgMusic()
                            else
                                pause()
                            setMusicMuted(!isMusicMuted)
                        }}>{isMusicMuted ? <span className="material-icons">music_off</span> : <span className="material-icons">music_note</span>}</button>
                    </span>
                </div>

                {/* WAITING / LEFT MESSAGES */}
                {!gameStarted && users.length < 2 && <h1 className='topInfoText'>Waiting for players to join... ({users.length}/4)</h1>}
                {!gameStarted && users.length >= 2 && currentUser === 'Player 1' &&
                    <div style={{textAlign:'center',margin:'20px'}}>
                        <h1 className='topInfoText'>{users.length} players in room</h1>
                        <button className='game-button orange' onClick={startGame} style={{fontSize:'18px',padding:'10px 30px'}}>
                            START GAME ({users.length} players)
                        </button>
                        {users.length < 4 && <p style={{color:'#ccc',marginTop:'8px'}}>Or wait for more players (max 4)</p>}
                    </div>
                }
                {!gameStarted && users.length >= 2 && currentUser !== 'Player 1' &&
                    <h1 className='topInfoText'>Waiting for Player 1 to start the game... ({users.length} players)</h1>
                }

                {gameStarted && <>

                    {gameOver ? <div>{winner !== '' && <><h1>GAME OVER</h1><h2>{winner} wins!</h2></>}</div> :
                    <div>
                        {/* OTHER PLAYERS' DECKS (shown at top) */}
                        <div style={{display:'flex',justifyContent:'center',gap:'30px',flexWrap:'wrap'}}>
                            {otherPlayers.map(player => (
                                <div key={player} className='player2Deck' style={{pointerEvents: 'none', minWidth:'150px'}}>
                                    <p className='playerDeckText' style={turn === player ? {color:'#ffd700',fontWeight:'bold'} : {}}>
                                        {player} ({(playerDecks[player] || []).length} cards)
                                    </p>
                                    {(playerDecks[player] || []).map((item, i) => (
                                        <img
                                            key={i}
                                            className='Card'
                                            src={require(`../assets/card-back.png`).default}
                                            style={{width:'40px',marginLeft: i > 0 ? '-25px' : '0'}}
                                            />
                                    ))}
                                    {turn === player && <Spinner />}
                                </div>
                            ))}
                        </div>
                        <br />

                        {/* MIDDLE - draw pile, played card, UNO button */}
                        <div className='middleInfo' style={turn !== currentUser ? {pointerEvents: 'none'} : null}>
                            <button className='game-button' disabled={turn !== currentUser} onClick={onCardDrawnHandler}>DRAW CARD</button>
                            {playedCardsPile && playedCardsPile.length>0 &&
                            <img
                                className='Card'
                                src={require(`../assets/cards-front/${playedCardsPile[playedCardsPile.length-1]}.png`).default}
                                /> }
                            <button className='game-button orange' disabled={myDeck.length !== 2} onClick={() => {
                                setUnoButtonPressed(!isUnoButtonPressed)
                                playUnoSound()
                            }}>UNO</button>
                        </div>

                        {/* Turn indicator */}
                        <div style={{textAlign:'center',margin:'5px 0',color: turn === currentUser ? '#ffd700' : '#aaa', fontSize:'14px',fontWeight:'bold'}}>
                            {turn === currentUser ? "YOUR TURN" : `${turn}'s turn`}
                            {direction === -1 && ' ↺'}
                        </div>

                        <br />

                        {/* MY DECK */}
                        <div className='player1Deck' style={turn === currentUser ? null : {pointerEvents: 'none'}}>
                            <p className='playerDeckText'>You ({currentUser})</p>
                            {myDeck.map((item, i) => (
                                <img
                                    key={i}
                                    className='Card'
                                    onClick={() => onCardPlayedHandler(item)}
                                    src={require(`../assets/cards-front/${item}.png`).default}
                                    />
                            ))}
                        </div>

                        {/* CHAT */}
                        <div className="chatBoxWrapper">
                            <div className="chat-box chat-box-player1">
                                <div className="chat-head">
                                    <h2>Chat Box</h2>
                                    {!isChatBoxHidden ?
                                    <span onClick={toggleChatBox} className="material-icons">keyboard_arrow_down</span> :
                                    <span onClick={toggleChatBox} className="material-icons">keyboard_arrow_up</span>}
                                </div>
                                <div className="chat-body">
                                    <div className="msg-insert">
                                        {messages.map((msg, i) => {
                                            if(msg.user === currentUser)
                                                return <div key={i} className="msg-send">{msg.text}</div>
                                            return <div key={i} className="msg-receive">{msg.user}: {msg.text}</div>
                                        })}
                                    </div>
                                    <div className="chat-text">
                                        <input type='text' placeholder='Type a message...' value={message} onChange={event => setMessage(event.target.value)} onKeyPress={event => event.key==='Enter' && sendMessage(event)} />
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div> }
                </> }
            </> : <h1>Room full</h1> }

            <br />
            <a href='/'><button className="game-button red">QUIT</button></a>
        </div>
    )
}

export default Game
